// ═══════════════════════════════════════════════════════
// DIABLO — El Diablo / Sparkmantown DGC
// 25 holes · Par 50 · Tags 1-50 + #666 memorial
// ═══════════════════════════════════════════════════════
let diabloState = { players: [], registrants: [], pendingResults: null };

async function loadDiabloPlayers() { const { data, error } = await db.from('diablo_players').select('*').order('tag', { ascending: true }); if (!error && data) diabloState.players = data; return diabloState.players; }

async function renderDiabloPage() { const isAdmin = state.currentUser && ['god','admin'].includes(state.currentUser.role); if (isAdmin) { const adminSection = document.getElementById('diabloAdminSection'); if (adminSection) adminSection.style.display = 'block'; } await loadDiabloPlayers(); loadDiabloLastWin(); loadDiabloStats(); renderDiabloLedger(''); }

function renderDiabloLedger(filter) { const el = document.getElementById('diabloTagList'); const fl = filter.toLowerCase(); const players = diabloState.players.filter(p => p.tag !== 666); const sorted = [...players].sort((a,b) => (a.tag ?? Infinity) - (b.tag ?? Infinity)); const visible = fl ? sorted.filter(p => p.name.toLowerCase().includes(fl)) : sorted; if (!visible.length) { el.innerHTML = '<div class="empty" style="color:#8b0000">No players found.</div>'; return; } el.innerHTML = visible.map(p => { const cls = p.tag === 1 ? 'd1' : p.tag === 2 ? 'd2' : p.tag === 3 ? 'd3' : ''; const change = p.last_change === 'up' ? '▲' : p.last_change === 'down' ? '▼' : '—'; const canDelete = state.currentUser && ['god','admin'].includes(state.currentUser.role); const changeColor = p.last_change === 'up' ? '#ff6600' : p.last_change === 'down' ? '#cc2200' : '#666'; return '<div class="diablo-tag-row"><span class="diablo-tag-num ' + cls + '">' + (p.tag ?? '—') + '</span><div style="flex:1"><div class="diablo-tag-name">' + p.name + '</div>' + (p.pdga ? '<div class="diablo-tag-pdga">PDGA #' + p.pdga + '</div>' : '') + '</div><span style="font-family:DM Mono,monospace;font-size:11px;color:' + changeColor + '">' + change + '</span>' + (canDelete ? '<button class="diablo-del-btn" title="Remove from El Diablo" onclick="deleteDiabloPlayer(' + attrStr(p.id) + ',' + attrStr(p.name) + ')">✕</button>' : '') + '</div>'; }).join(''); }
async function deleteDiabloPlayer(id, name) { if (!confirm('Remove ' + name + ' from the El Diablo roster?\n\nThis does not touch the main Boulder tag ledger, and it cannot be undone.')) return; try { const { error } = await db.from('diablo_players').delete().eq('id', id); if (error) { console.warn('deleteDiabloPlayer:', error); return showToast('Could not remove ' + name + '.', true); } } catch(e) { console.warn('deleteDiabloPlayer:', e); return showToast('Could not remove ' + name + '.', true); } const idx = diabloMoney.players.findIndex(pl => pl.name === name); if (idx >= 0) diabloMoney.players.splice(idx, 1); await loadDiabloPlayers(); renderDiabloLedger(document.getElementById('diabloSearch') ? document.getElementById('diabloSearch').value : ''); renderDiabloQuickGrid(); renderDiabloSelectedPlayers(); showToast(name + ' removed.'); }

function filterDiabloLedger(val) { renderDiabloLedger(val); }

function searchDiabloPlayer(val) { const dd = document.getElementById('diabloDropdown'); if (!val || val.length < 2) { dd.style.display = 'none'; return; } const fl = val.toLowerCase(); const diabloMatches = diabloState.players.filter(p => p.name.toLowerCase().includes(fl)).slice(0, 4); const boulderMatches = state.players.filter(p => p.name.toLowerCase().includes(fl) && !diabloState.players.find(d => d.name === p.name)).slice(0, 3); const all = [...diabloMatches, ...boulderMatches]; if (!all.length) { dd.style.display = 'none'; return; } dd.style.display = 'block'; dd.innerHTML = all.map(p => { const fromBoulder = !diabloState.players.find(d => d.name === p.name); return '<div onmousedown="event.preventDefault();selectDiabloPlayer(' + attrStr(p.name) + ',' + (p.tag||'null') + ')" style="padding:10px 12px;cursor:pointer;border-bottom:1px solid #8b0000;font-size:14px;color:#ffcccc;" onmouseenter="this.style.background=\'#2d0000\'" onmouseleave="this.style.background=\'\'"><strong>' + p.name + '</strong>' + (fromBoulder ? ' <span style="color:#8b0000;font-size:10px">(from Boulder)</span>' : '') + (p.tag ? '<span style="font-size:11px;color:#8b0000;margin-left:8px">Tag #' + p.tag + '</span>' : '') + '</div>'; }).join(''); }

function selectDiabloPlayer(name, tag) { document.getElementById('diabloRegSearch').value = name; if (tag) document.getElementById('diabloRegTag').value = tag; document.getElementById('diabloDropdown').style.display = 'none'; }

function addDiabloRegistrant() { const name = document.getElementById('diabloRegSearch').value.trim(); const tag = parseInt(document.getElementById('diabloRegTag').value); if (!name) return showToast('Enter a player name.', true); if (!tag || tag < 1 || tag > 50) return showToast('Enter a valid tag # (1-50).', true); if (diabloState.registrants.find(r => r.name === name)) return showToast(name + ' already in match.', true); if (diabloState.registrants.find(r => r.tag === tag)) return showToast('Tag #' + tag + ' already in match.', true); diabloState.registrants.push({ name, tag, score: null }); clearDiabloForm(); renderDiabloRegistrants(); showToast(name + ' added — Tag #' + tag); }

function clearDiabloForm() { document.getElementById('diabloRegSearch').value = ''; document.getElementById('diabloRegTag').value = ''; document.getElementById('diabloDropdown').style.display = 'none'; }

function renderDiabloRegistrants() { const el = document.getElementById('diabloRegistrantList'); const count = document.getElementById('diabloRegCount'); const btn = document.getElementById('diabloProceedBtn'); count.textContent = '(' + diabloState.registrants.length + ' players)'; btn.style.display = diabloState.registrants.length >= 2 ? 'flex' : 'none'; if (!diabloState.registrants.length) { el.innerHTML = '<div class="empty" style="color:#8b0000">No players added yet.</div>'; return; } el.innerHTML = [...diabloState.registrants].sort((a,b) => a.tag - b.tag).map(r => '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:#2d0000;border-radius:8px;margin-bottom:6px;"><span style="font-family:Bebas Neue,sans-serif;font-size:22px;color:#cc2200;min-width:38px;">#' + r.tag + '</span><span style="flex:1;font-size:14px;color:#ffcccc;">' + r.name + '</span><button onclick="removeDiabloRegistrant(' + attrStr(r.name) + ')" style="background:rgba(204,34,0,0.1);color:#cc2200;border:1px solid rgba(204,34,0,0.2);border-radius:6px;padding:5px 10px;cursor:pointer;font-size:12px;">✕</button></div>').join(''); }

function removeDiabloRegistrant(name) { diabloState.registrants = diabloState.registrants.filter(r => r.name !== name); renderDiabloRegistrants(); }

function diabloGoToScoring() { setDiabloStep(2); const el = document.getElementById('diabloScoreList'); const btn = document.getElementById('diabloCalcBtn'); const sorted = [...diabloState.registrants].sort((a,b) => a.tag - b.tag); btn.disabled = true; el.innerHTML = sorted.map(r => { const sid = 'dscore_' + r.name.replace(/\W/g,'_'); return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:#2d0000;border:1px solid #8b0000;border-radius:8px;margin-bottom:6px;"><span style="font-family:Bebas Neue,sans-serif;font-size:22px;color:#cc2200;min-width:38px;">#' + r.tag + '</span><span style="flex:1;color:#ffcccc;">' + r.name + '</span><input type="number" min="1" max="150" placeholder="strokes" id="' + sid + '" style="width:80px;text-align:center;background:#1a0000;border:1px solid #8b0000;color:#ffcccc;border-radius:6px;padding:8px;" onchange="saveDiabloScore(' + attrStr(r.name) + ', this.value)"></div>'; }).join(''); }

function saveDiabloScore(name, val) { const score = parseInt(val); if (!score || isNaN(score)) return; const r = diabloState.registrants.find(r => r.name === name); if (r) r.score = score; const allScored = diabloState.registrants.every(r => r.score && !isNaN(r.score)); document.getElementById('diabloCalcBtn').disabled = !allScored; }

function diabloCalculateResults() { const scored = diabloState.registrants.map(r => { const inp = document.getElementById('dscore_' + r.name.replace(/\W/g,'_')); return { ...r, score: r.score || (inp ? parseInt(inp.value) : null) }; }); if (scored.some(r => !r.score || isNaN(r.score))) return showToast('All players need a score.', true); scored.sort((a,b) => a.score !== b.score ? a.score - b.score : a.tag - b.tag); const tags = [...scored].map(r => r.tag).sort((a,b) => a-b); const results = scored.map((r,i) => ({ ...r, newTag: tags[i], finish: i+1 })); diabloState.pendingResults = results; setDiabloStep(3); document.getElementById('diabloResultsList').innerHTML = results.map(r => { const better = r.newTag < r.tag, worse = r.newTag > r.tag; const diff = r.tag - r.newTag; const diffStr = diff > 0 ? '+' + diff : diff < 0 ? String(diff) : '±0'; const finColor = r.finish===1?'#ffd700':r.finish===2?'#ff6600':r.finish===3?'#cc2200':'#666'; const moveColor = better?'#ff6600':worse?'#cc2200':'#666'; return '<div style="display:flex;align-items:center;gap:10px;padding:12px 14px;background:#1a0000;border:1px solid #8b0000;border-radius:8px;margin-bottom:8px;flex-wrap:wrap;"><span style="font-family:Bebas Neue,sans-serif;font-size:26px;min-width:30px;color:' + finColor + '">' + r.finish + '</span><span style="flex:1;font-weight:500;color:#ffcccc;">' + r.name + '</span><span style="font-family:DM Mono,monospace;font-size:12px;color:#8b0000;">' + r.score + '✦</span><span style="font-family:DM Mono,monospace;font-size:13px;color:#666;">#' + r.tag + '</span><span style="font-size:16px;color:' + moveColor + '">' + (better?'▲':worse?'▼':'—') + '</span><span style="font-family:Bebas Neue,sans-serif;font-size:22px;color:' + moveColor + '">#' + r.newTag + '</span><span style="font-size:10px;color:#666;font-family:DM Mono,monospace;">' + diffStr + '</span></div>'; }).join(''); }

async function diabloCommitResults() { if (!diabloState.pendingResults) return; for (const r of diabloState.pendingResults) { const player = diabloState.players.find(p => p.name === r.name); if (player) { const change = r.newTag < player.tag ? 'up' : r.newTag > player.tag ? 'down' : 'same'; await db.from('diablo_players').update({ tag: r.newTag, last_change: change }).eq('id', player.id); player.tag = r.newTag; player.last_change = change; } else { const { data } = await db.from('diablo_players').insert({ name: r.name, tag: r.newTag, role: 'player', last_change: 'same' }).select().single(); if (data) diabloState.players.push(data); } } await db.from('diablo_match_history').insert({ date: localDateStr(), player_count: diabloState.pendingResults.length, results: JSON.stringify(diabloState.pendingResults) }); diabloState.registrants = []; diabloState.pendingResults = null; setDiabloStep(1); renderDiabloRegistrants(); renderDiabloLedger(''); showToast('🔥 Diablo tags updated!'); }

function setDiabloStep(n) { [1,2,3].forEach(i => { document.getElementById('diabloMatchStep'+i).style.display = i===n?'block':'none'; const dot = document.getElementById('dstep'+i+'dot'); if (dot) { dot.classList.toggle('active', i===n); dot.classList.toggle('done', i<n); } }); } function diabloBackToStep1() { setDiabloStep(1); } function diabloBackToStep2() { setDiabloStep(2); }

async function addDiabloPlayer() { const name = document.getElementById('diabloNewName').value.trim(); const pdga = document.getElementById('diabloNewPDGA').value.trim(); const tagVal = document.getElementById('diabloNewTag').value.trim(); const tag = tagVal ? parseInt(tagVal) : null; if (!name) return showToast('Enter a name.', true); if (tag && diabloState.players.find(p => p.tag === tag)) return showToast('Tag #' + tag + ' already assigned.', true); const { error } = await db.from('diablo_players').insert({ name, pdga: pdga||null, tag, role: 'player', last_change: 'same' }); if (error) return showToast('Error adding player.', true); document.getElementById('diabloNewName').value = ''; document.getElementById('diabloNewPDGA').value = ''; document.getElementById('diabloNewTag').value = ''; showToast(name + ' added to El Diablo! 🔥'); await loadDiabloPlayers(); renderDiabloLedger(''); renderDiabloQuickGrid(); }

// ═══════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════
// DIABLO MONEY MATCH + FLAMES
// ═══════════════════════════════════════════════════════
const DIABLO_TEAM_NAMES = ['Hellfire','Brimstone','Inferno','Damnation','Perdition','Purgatory','Gehenna','Abaddon','Tartarus','Sheol','Cocytus','Phlegethon','Acheron','Styx','Lethe','Avernus','Malebolge','Pandemonium','Erebus','Naraka','Jahannam','Diyu','Xibalba','Niflheim','Muspelheim','Hel','Valhalla','Abyss','Void','Oblivion','Nether','Limbo','Chasm','Abyss','Cinder','Ember','Ash','Soot','Char','Scorch','Blaze','Pyre','Torch','Beacon','Flare','Spark','Ignite','Kindle','Smolder','Combust','Fervent','Ardent','Fervid','Torrid','Sultry','Incandescent','Searing','Scalding','Cauterize','Brand','Singe','Char','Incinerate','Immolate','Cremate','Calcinate','Slag','Clinker','Coke','Charcoal','Pitch','Tar','Resin','Creosote','Sulfur','Brimstone','Nitre','Saltpeter','Phosphor','Magnesium','Thermite','Napalm','Hellion','Demon','Devil','Beelzebub','Belial','Asmodeus','Azazel','Mammon','Belphegor','Leviathan','Moloch','Lilith','Samael','Mephisto','Lucifer','Diablo','Satan','Iblis','Shaitan','Ahriman','Angra','Mainyu','Mara','Ravana','Mahishasura','Kali','Durga','Shiva','Rudra','Bhairava','Vetala','Pishaca','Rakshasa','Yaksha','Asura','Daitya','Deva','Naga','Garuda','Vritra','Namuchi','Vala','Shambara','Svarbhanu','Ketu','Rahu','Varuna','Agni','Indra','Surya','Chandra','Budha','Mangala','Shukra','Shani','Yama','Nirrti','Vayu','Kubera','Ishana','Soma','Vishnu','Brahma','Vyasa','Narada','Kashyapa','Daksha','Marichi','Angiras','Atri','Pulastya','Pulaha','Kratu','Vasishtha','Bhrigu','Agastya','Gautama','Bharadvaja','Jamadagni','Vishvamitra','Garga','Kanva','Kutsa','Medhatithi','Nodhas','Parashara','Sandhi','Shakata','Shyena','Sobhari','Svana','Trita','Tryaruna','Tumbu','Ushanas','Vamadeva','Vatsa','Vena','Vittahavya','Vrisha','Vyashti','Yaksha','Yaska','Yati','Yayati','Zephyr','Zeal','Zenith','Zero','Zest','Zig','Zap','Zip','Zoom','Zone'];
let diabloActiveMatches = [];
let diabloLastPlayed = {};
async function loadDiabloRecency() { try { const { data } = await db.from('diablo_money_matches').select('created_at,players').order('created_at', { ascending: false }).limit(50); const map = {}; (data || []).forEach(m => { let ps = []; try { ps = typeof m.players === 'string' ? JSON.parse(m.players) : (m.players || []); } catch(e) { return; } ps.forEach(pl => { if (pl && pl.name && !map[pl.name]) map[pl.name] = m.created_at; }); }); diabloLastPlayed = map; } catch(e) { console.warn('loadDiabloRecency:', e); } renderDiabloQuickGrid(); }
let diabloMoney = { format: null, players: [], scores: [], currentHole: 1, frontierHole: 1, totalHoles: 25, buyin: 5, matchId: null, teamsLocked: false, teamNameMap: {}, teamAssignments: [], caliPlayer: null };
function toggleDiabloAddPlayer() { const b = document.getElementById('diabloAddPlayerBody'), h = document.getElementById('diabloAddPlayerHead'); if (!b) return; const isOpen = b.style.display !== 'none'; b.style.display = isOpen ? 'none' : 'block'; if (h) h.classList.toggle('open', !isOpen); }
function openDiabloPlay() { ['diabloSetupScreen','diabloScorecardScreen','diabloPayoutScreen'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; }); const fs = document.getElementById('diabloFormatScreen'); if (fs) fs.style.display = 'block'; checkForActiveMatch(); loadDiabloRecency(); setTimeout(() => { const anchor = document.getElementById('diabloPlayAnchor'); if (anchor) anchor.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 50); }
function closeDiabloPlay() { ['diabloSetupScreen','diabloResumeScreen','diabloScorecardScreen','diabloPayoutScreen'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; }); document.getElementById('diabloFormatScreen').style.display = 'block'; diabloMoney = { format: null, players: [], scores: [], currentHole: 1, frontierHole: 1, totalHoles: 25, buyin: 5, matchId: null, teamsLocked: false, teamNameMap: {}, teamAssignments: [], caliPlayer: null }; const ag = document.getElementById('diabloResumeScreen'); if (ag) { ag.style.display = 'none'; ag.innerHTML = ''; } }
async function checkForActiveMatch() { try { const { data } = await db.from('diablo_money_matches').select('*').eq('status','active').order('created_at',{ascending:false}).limit(2); diabloActiveMatches = (data || []).slice(0, 2); } catch(e) { console.warn('checkForActiveMatch:', e); diabloActiveMatches = []; } renderDiabloActiveGames(); }
function renderDiabloActiveGames() { const wrap = document.getElementById('diabloResumeScreen'); if (!wrap) return; const onFormat = (document.getElementById('diabloFormatScreen') || {}).style; const list = diabloActiveMatches || []; if (!list.length || (onFormat && onFormat.display === 'none')) { wrap.style.display = 'none'; wrap.innerHTML = ''; return; } wrap.style.display = 'block'; wrap.innerHTML = '<div class="diablo-eyebrow" style="margin-top:22px;">\u26A1 ACTIVE GAME' + (list.length > 1 ? 'S' : '') + ' \u00b7 PICK UP WHERE YOU LEFT OFF</div>' + list.map(m => { let players = []; try { players = typeof m.players === 'string' ? JSON.parse(m.players) : (m.players || []); } catch(e) { players = []; } const label = m.format === 'tags' ? 'Tag Match' : String(m.format || '').includes('doubles') ? 'Doubles Money Match' : 'Singles Money Match'; return '<div class="diablo-card" style="position:relative;z-index:1;border-color:#cc2200;margin-bottom:10px;padding:14px;">' + '<div style="color:#ffd700;font-family:DM Mono,monospace;font-size:12px;letter-spacing:1px;margin-bottom:6px;">' + label + '</div>' + '<div style="color:#ffcccc;font-size:13px;line-height:1.5;margin-bottom:12px;">' + (players.length ? players.map(pl => pl.name).join(', ') : 'No players recorded') + '<br><span style="color:#8b0000;font-family:DM Mono,monospace;font-size:11px;">HOLE ' + (m.current_hole || 1) + ' OF ' + (m.total_holes || 25) + '</span></div>' + '<div style="display:flex;gap:8px;">' + '<button class="diablo-btn diablo-btn-primary" style="flex:1;justify-content:center;" onclick="resumeDiabloMatchById(' + attrStr(m.id) + ')">\u25B6 Resume</button>' + '<button class="diablo-btn diablo-btn-secondary" style="flex-shrink:0;color:#cc2200;border-color:#cc2200;" onclick="abandonDiabloMatchById(' + attrStr(m.id) + ')">\u2715</button>' + '</div></div>'; }).join(''); }
async function resumeDiabloMatchById(id) { const m = (diabloActiveMatches || []).find(x => String(x.id) === String(id)); if (!m) { showToast('That game is no longer available.', true); return; } let players = []; try { players = typeof m.players === 'string' ? JSON.parse(m.players) : (m.players || []); } catch(e) { players = []; } diabloMoney.matchId = m.id; diabloMoney.format = m.format; diabloMoney.buyin = m.buyin; diabloMoney.currentHole = m.current_hole || 1; diabloMoney.totalHoles = m.total_holes || 25; diabloMoney.players = players; await resumeDiabloMatch(); }
async function abandonDiabloMatchById(id) { if (!confirm('Abandon this game? It comes off the active list and cannot be resumed.')) return; try { await db.from('diablo_money_matches').update({ status: 'abandoned' }).eq('id', id); } catch(e) { console.warn('abandon:', e); } if (String(diabloMoney.matchId) === String(id)) diabloMoney.matchId = null; await checkForActiveMatch(); showToast('Game abandoned.'); }
async function resumeDiabloMatch() { try { const { data: scoreData } = await db.from('diablo_money_scores').select('*').eq('match_id', diabloMoney.matchId); diabloMoney.scores = diabloMoney.players.map(p => ({ ...p, holes: [], total: 0 })); if (scoreData) { scoreData.forEach(s => { const player = diabloMoney.scores.find(p => p.name === s.player_name); if (player) { player.holes[s.hole - 1] = s.score; player.total += s.score; } }); } diabloMoney.frontierHole = Math.max(1, diabloMoney.currentHole || 1); document.getElementById('diabloResumeScreen').style.display = 'none'; showDiabloScorecard(); } catch(e) { showToast('Error resuming match.', true); } }

function lockDiabloPlayers() { if (diabloMoney.players.length < 2) return showToast('Need at least 2 players.', true); diabloMoney.teamsLocked = true; diabloMoney.caliPlayer = null; diabloMoney.players.forEach(p => { p.cali = false; p.team = null; p.buyinMultiplier = 1; }); diabloMoney.teamNameMap = {}; diabloMoney.teamAssignments = []; renderDiabloSelectedPlayers(); updateDiabloPot(); }
function setCaliMult(mult) { const caliP = diabloMoney.players.find(p => p.cali); if (caliP) caliP.buyinMultiplier = mult; const caliTeam = diabloMoney.teamAssignments && diabloMoney.teamAssignments.find(t => t.isCali); if (caliTeam) caliTeam.buyinMultiplier = mult; renderDiabloSelectedPlayers(); updateDiabloPot(); } function clearTeams() { diabloMoney.players.forEach(p => { if (!p.cali) { p.team = null; } }); diabloMoney.teamAssignments = []; diabloMoney.teamNameMap = {}; renderDiabloSelectedPlayers(); updateDiabloPot(); }
function randomizeTeams() { const allPlayers = [...diabloMoney.players]; const shuffled = allPlayers.sort(() => Math.random() - 0.5); const isOdd = shuffled.length % 2 !== 0; const caliPerson = isOdd ? shuffled[shuffled.length - 1] : null; const teamPlayers = isOdd ? shuffled.slice(0, shuffled.length - 1) : shuffled; const numTeams = teamPlayers.length / 2; const usedNames = []; const assignments = []; for (let i = 0; i < numTeams; i++) { let pick; do { pick = DIABLO_TEAM_NAMES[Math.floor(Math.random() * DIABLO_TEAM_NAMES.length)]; } while (usedNames.includes(pick)); usedNames.push(pick); const p1 = teamPlayers[i * 2]; const p2 = teamPlayers[i * 2 + 1]; p1.team = 'team' + (i + 1); p1.cali = false; p2.team = 'team' + (i + 1); p2.cali = false; diabloMoney.teamNameMap['team' + (i + 1)] = pick; assignments.push({ name: pick, players: [p1.name, p2.name], key: 'team' + (i + 1), isCali: false }); } if (caliPerson) { let caliName; do { caliName = DIABLO_TEAM_NAMES[Math.floor(Math.random() * DIABLO_TEAM_NAMES.length)]; } while (usedNames.includes(caliName)); caliPerson.cali = true; caliPerson.team = 'cali'; caliPerson.buyinMultiplier = diabloMoney.players.find(p => p.name === caliPerson.name)?.buyinMultiplier || 1; diabloMoney.caliPlayer = caliPerson.name; diabloMoney.teamNameMap['cali'] = caliName; assignments.push({ name: caliName, players: [caliPerson.name], key: 'cali', isCali: true, buyinMultiplier: caliPerson.buyinMultiplier }); } diabloMoney.teamAssignments = assignments; const el = document.getElementById('diabloSelectedPlayers'); let frame = 0; const names = shuffled.map(p => p.name); const interval = setInterval(() => { frame++; const scrambled = [...names].sort(() => Math.random() - 0.5); el.innerHTML = '<div style="font-family:Bebas Neue,sans-serif;font-size:16px;color:' + (frame%2===0?'#ffd700':'#cc2200') + ';letter-spacing:2px;text-align:center;padding:20px;">' + scrambled.join(' · ') + '</div>'; if (frame >= 20) { clearInterval(interval); renderDiabloSelectedPlayers(); updateDiabloPot(); showToast('Teams set! 🎲'); } }, 80); }
function backToDiabloFormat() { ['diabloSetupScreen','diabloResumeScreen','diabloScorecardScreen','diabloPayoutScreen'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; }); document.getElementById('diabloFormatScreen').style.display = 'block'; renderDiabloActiveGames(); diabloMoney.format = null; diabloMoney.players = []; diabloMoney.teamsLocked = false; diabloMoney.teamNameMap = {}; diabloMoney.teamAssignments = []; diabloMoney.caliPlayer = null; }
function selectDiabloFormat(format) { diabloMoney.format = format; document.getElementById('diabloFormatScreen').style.display = 'none'; renderDiabloActiveGames(); document.getElementById('diabloSetupScreen').style.display = 'block'; const isDoubles = format === 'money-doubles'; const isMoney = format !== 'tags'; document.getElementById('diabloSetupTitle').textContent = format === 'tags' ? '🏷️ Tag Match — Who\'s Playing?' : isDoubles ? '👥 Doubles — Who\'s Playing?' : '💰 Singles — Who\'s Playing?'; document.getElementById('diabloBuyinSection').style.display = isMoney ? 'block' : 'none'; document.getElementById('diabloTeamAssign').style.display = 'none'; diabloMoney.players = []; diabloMoney.teamsLocked = false; renderDiabloQuickGrid(); renderDiabloSelectedPlayers(); }
function renderDiabloQuickGrid() { const el = document.getElementById('diabloQuickPlayerGrid'); if (!el) return; const inGame = n => diabloMoney.players.some(pl => pl.name === n); const lastPlayed = n => diabloLastPlayed[n] || ''; const ordered = diabloState.players.filter(p => p.tag !== 666).slice().sort((a, b) => { const sa = inGame(a.name) ? 0 : 1, sb = inGame(b.name) ? 0 : 1; if (sa !== sb) return sa - sb; const la = lastPlayed(a.name), lb = lastPlayed(b.name); if (la && lb) { if (la !== lb) return la < lb ? 1 : -1; } else if (la !== lb) { return la ? -1 : 1; } return (a.tag == null ? 9999 : a.tag) - (b.tag == null ? 9999 : b.tag); }); el.innerHTML = ordered.map(p => { const selected = diabloMoney.players.find(pl => pl.name === p.name); return '<button onclick="toggleDiabloPlayer(' + attrStr(p.name) + ')" style="padding:8px 14px;border-radius:20px;border:1px solid ' + (selected ? '#cc2200' : '#8b0000') + ';background:' + (selected ? '#cc2200' : 'transparent') + ';color:' + (selected ? '#fff' : '#ffcccc') + ';font-size:13px;cursor:pointer;transition:all 0.2s;">' + p.name + (selected ? ' ✓' : '') + '</button>'; }).join(''); }
function toggleDiabloPlayer(name) { const existing = diabloMoney.players.findIndex(p => p.name === name); if (existing >= 0) { diabloMoney.players.splice(existing, 1); } else { diabloMoney.players.push({ name, team: null, cali: false, buyinMultiplier: 1 }); } renderDiabloQuickGrid(); renderDiabloSelectedPlayers(); updateDiabloPot(); }
function toggleDiabloGuestInput() { const row = document.getElementById('diabloGuestInputRow'); const head = document.getElementById('diabloNewVictimHead'); if (!row) return; const isOpen = row.style.display !== 'none'; row.style.display = isOpen ? 'none' : 'block'; if (head) head.classList.toggle('open', !isOpen); if (!isOpen) setTimeout(() => { const inp = document.getElementById('diabloNewVictimName'); if (inp) inp.focus(); }, 50); }
function selectDiabloSearchResult(name) { diabloLastPlayed[name] = diabloLastPlayed[name] || new Date().toISOString(); if (!diabloMoney.players.find(p => p.name === name)) toggleDiabloPlayer(name); const inp = document.getElementById('diabloMoneyPlayerInput'); if (inp) inp.value = ''; const dd = document.getElementById('diabloMoneyDropdown'); if (dd) dd.style.display = 'none'; showToast(name + ' added.'); }
async function addDiabloGuestPlayer() { const el = document.getElementById('diabloNewVictimName'); const name = (el ? el.value : '').trim(); if (!name) return showToast('Enter a name.', true); if (diabloMoney.players.find(p => p.name === name)) return showToast(name + ' is already in this game.', true); if (!diabloState.players.find(p => p.name === name)) { const { error } = await db.from('diablo_players').insert({ name, pdga: null, tag: null, role: 'player', last_change: 'same' }); if (error) { console.warn('add diablo player:', error); showToast('Could not save to the roster \u2014 added to this game only.', true); } else { await loadDiabloPlayers(); renderDiabloLedger(''); } } diabloLastPlayed[name] = new Date().toISOString(); if (!diabloMoney.players.find(p => p.name === name)) toggleDiabloPlayer(name); if (el) el.value = ''; const row = document.getElementById('diabloGuestInputRow'); if (row) row.style.display = 'none'; const head = document.getElementById('diabloNewVictimHead'); if (head) head.classList.remove('open'); renderDiabloQuickGrid(); renderDiabloSelectedPlayers(); updateDiabloPot(); showToast(name + ' added. \uD83D\uDD25'); }
function checkCaliNeeded() { const isDoubles = diabloMoney.format === 'money-doubles'; if (isDoubles && diabloMoney.players.length % 2 !== 0 && diabloMoney.players.length > 0) { const lastPlayer = diabloMoney.players[diabloMoney.players.length - 1]; if (!lastPlayer.cali) { lastPlayer.cali = true; lastPlayer.team = 'cali'; showToast(lastPlayer.name + ' is Cali — odd player out.', false); } renderDiabloSelectedPlayers(); } }
function renderDiabloSelectedPlayers() { const el = document.getElementById('diabloSelectedPlayers'); const lockBtn = document.getElementById('diabloLockBtn'); const isDoubles = diabloMoney.format === 'money-doubles'; if (!diabloMoney.players.length) { el.innerHTML = '<div style="color:#8b0000;font-size:13px;font-family:DM Mono,monospace;padding:8px 0;">Tap names above to add players.</div>'; document.getElementById('diabloStartRoundBtn').style.display = 'none'; if (lockBtn) lockBtn.style.display = 'none'; return; } if (!isDoubles) { if (lockBtn) lockBtn.style.display = 'none'; document.getElementById('diabloStartRoundBtn').style.display = diabloMoney.players.length >= 2 ? 'flex' : 'none'; el.innerHTML = diabloMoney.players.map(p => '<div class="diablo-buyin-row"><span class="diablo-buyin-name">' + p.name + (p.guest ? ' <span style="color:#8b0000;font-size:10px">(guest)</span>' : '') + '</span><button onclick="toggleDiabloPlayer(' + attrStr(p.name) + ')" style="background:transparent;border:none;color:#8b0000;cursor:pointer;font-size:16px;padding:0 4px;">✕</button></div>' ).join(''); return; } if (!diabloMoney.teamsLocked) { if (lockBtn) lockBtn.style.display = diabloMoney.players.length >= 2 ? 'flex' : 'none'; document.getElementById('diabloStartRoundBtn').style.display = 'none'; const isOdd = diabloMoney.players.length % 2 !== 0; el.innerHTML = '<div style="color:#8b0000;font-size:11px;font-family:DM Mono,monospace;letter-spacing:1px;margin-bottom:8px;">' + diabloMoney.players.length + ' PLAYER' + (diabloMoney.players.length !== 1 ? 'S' : '') + (isOdd ? ' \xb7 ODD — last player will be Cali' : ' \xb7 even — ready to pair') + '</div>' + diabloMoney.players.map(p => '<div class="diablo-buyin-row"><span class="diablo-buyin-name">' + p.name + (p.guest ? ' <span style="color:#8b0000;font-size:10px">(guest)</span>' : '') + '</span><button onclick="toggleDiabloPlayer(' + attrStr(p.name) + ')" style="background:transparent;border:none;color:#8b0000;cursor:pointer;font-size:16px;padding:0 4px;">✕</button></div>' ).join(''); return; } if (lockBtn) lockBtn.style.display = 'none'; const caliP = diabloMoney.players.find(p => p.cali); const teamsFormed = diabloMoney.teamAssignments && diabloMoney.teamAssignments.length > 0; const startBtn = document.getElementById('diabloStartRoundBtn'); if (!teamsFormed) { startBtn.style.display = 'none'; let html = ''; if (caliP) { html += '<div style="background:#1a0000;border:1px solid #666;border-radius:8px;padding:14px;margin-bottom:12px;"><div style="font-size:11px;color:#666;letter-spacing:2px;font-family:DM Mono,monospace;margin-bottom:8px;">CALI — ODD PLAYER OUT</div><div style="font-size:16px;color:#ffcccc;font-weight:600;margin-bottom:10px;">' + caliP.name + '</div><div style="font-size:11px;color:#8b0000;font-family:DM Mono,monospace;margin-bottom:8px;">BUY-IN:</div><div style="display:flex;gap:8px;"><button onclick="setCaliMult(1)" style="flex:1;padding:10px;border-radius:8px;border:1px solid ' + (caliP.buyinMultiplier===1?'#cc2200':'#8b0000') + ';background:' + (caliP.buyinMultiplier===1?'#cc2200':'transparent') + ';color:' + (caliP.buyinMultiplier===1?'#fff':'#8b0000') + ';font-family:Bebas Neue,sans-serif;font-size:18px;cursor:pointer;">1x — HALF</button><button onclick="setCaliMult(2)" style="flex:1;padding:10px;border-radius:8px;border:1px solid ' + (caliP.buyinMultiplier===2?'#cc2200':'#8b0000') + ';background:' + (caliP.buyinMultiplier===2?'#cc2200':'transparent') + ';color:' + (caliP.buyinMultiplier===2?'#fff':'#8b0000') + ';font-family:Bebas Neue,sans-serif;font-size:18px;cursor:pointer;">2x — FULL</button></div></div>'; } html += '<button class="diablo-btn diablo-btn-primary" onclick="randomizeTeams()" style="width:100%;justify-content:center;font-size:18px;padding:16px;">🎲 RANDOMIZE TEAMS</button>'; el.innerHTML = html; return; } let html = ''; diabloMoney.teamAssignments.filter(t => !t.isCali).forEach(team => { html += '<div style="background:#1a0000;border:1px solid #8b0000;border-radius:8px;padding:14px;margin-bottom:10px;"><div style="font-family:Bebas Neue,sans-serif;font-size:20px;color:#ff3300;letter-spacing:2px;margin-bottom:6px;">' + team.name + '</div>' + team.players.map(name => '<div style="font-size:15px;color:#ffcccc;padding:2px 0;">' + name + '</div>').join('') + '</div>'; }); const caliTeam = diabloMoney.teamAssignments.find(t => t.isCali); if (caliTeam) { const buyinMult = caliTeam.buyinMultiplier || diabloMoney.players.find(p => p.cali)?.buyinMultiplier || 1; html += '<div style="background:#1a0000;border:1px solid #cc2200;border-radius:8px;padding:14px;margin-bottom:10px;"><div style="font-family:Bebas Neue,sans-serif;font-size:20px;color:#ff3300;letter-spacing:2px;margin-bottom:2px;">' + caliTeam.name + '</div><div style="font-size:10px;color:#8b0000;font-family:DM Mono,monospace;letter-spacing:2px;margin-bottom:6px;">CALI</div>' + caliTeam.players.map(name => '<div style="font-size:15px;color:#ffcccc;padding:2px 0;">' + name + '</div>').join('') + '<div style="margin-top:8px;display:flex;gap:8px;"><button onclick="setCaliMult(1)" style="flex:1;padding:8px;border-radius:6px;border:1px solid ' + (buyinMult===1?'#cc2200':'#8b0000') + ';background:' + (buyinMult===1?'#cc2200':'transparent') + ';color:' + (buyinMult===1?'#fff':'#8b0000') + ';font-family:Bebas Neue,sans-serif;font-size:14px;cursor:pointer;">1x HALF</button><button onclick="setCaliMult(2)" style="flex:1;padding:8px;border-radius:6px;border:1px solid ' + (buyinMult===2?'#cc2200':'#8b0000') + ';background:' + (buyinMult===2?'#cc2200':'transparent') + ';color:' + (buyinMult===2?'#fff':'#8b0000') + ';font-family:Bebas Neue,sans-serif;font-size:14px;cursor:pointer;">2x FULL</button></div></div>'; } html += '<button class="diablo-btn diablo-btn-secondary" onclick="clearTeams()" style="width:100%;justify-content:center;margin-bottom:8px;">🎲 Re-Randomize</button>'; el.innerHTML = html; startBtn.style.display = 'flex'; }
function setDiabloTeam(idx, team) { diabloMoney.players[idx].team = team; diabloMoney.players[idx].cali = (team === 'cali'); if (team !== 'cali' && !diabloMoney.teamNameMap[team]) { const usedNames = Object.values(diabloMoney.teamNameMap); let pick; do { pick = DIABLO_TEAM_NAMES[Math.floor(Math.random() * DIABLO_TEAM_NAMES.length)]; } while (usedNames.includes(pick)); diabloMoney.teamNameMap[team] = pick; } renderDiabloSelectedPlayers(); updateDiabloPot(); }
function setCaliMultiplier(idx, mult) { diabloMoney.players[idx].buyinMultiplier = mult; renderDiabloSelectedPlayers(); updateDiabloPot(); }
function updateDiabloPot() { const buyin = parseFloat(document.getElementById('diabloBuyinAmount')?.value) || 5; diabloMoney.buyin = buyin; const isDoubles = diabloMoney.format === 'money-doubles'; let total = 0; if (isDoubles) { diabloMoney.players.forEach(p => { const mult = p.cali ? (p.buyinMultiplier || 1) : 2; total += buyin * mult; }); } else { total = diabloMoney.players.length * buyin; } const el = document.getElementById('diabloPotDisplay'); if (el) { const perPlayer = isDoubles ? buyin + '/player (\xd72 per team, \xd7' + (diabloMoney.players.find(p=>p.cali)?.buyinMultiplier||1) + ' Cali)' : buyin + '/player'; el.textContent = 'Total pot: $' + total.toFixed(0) + ' \xb7 $' + perPlayer; } }
function searchDiabloMoneyPlayer(val) { const dd = document.getElementById('diabloMoneyDropdown'); if (!val || val.length < 2) { dd.style.display = 'none'; return; } const fl = val.toLowerCase(); const matches = [...diabloState.players, ...state.players.filter(p => !diabloState.players.find(d => d.name === p.name))].filter(p => p.name.toLowerCase().includes(fl) && !diabloMoney.players.find(pl => pl.name === p.name)).slice(0, 6); if (!matches.length) { dd.style.display = 'none'; return; } dd.style.display = 'block'; dd.innerHTML = matches.map(p => '<div onmousedown="event.preventDefault();selectDiabloSearchResult(' + attrStr(p.name) + ');" style="padding:10px 12px;cursor:pointer;border-bottom:1px solid #8b0000;font-size:14px;color:#ffcccc;" onmouseenter="this.style.background=\'#2d0000\'" onmouseleave="this.style.background=\'\'" ><strong>' + p.name + '</strong></div>').join(''); }
async function startDiabloRound() { diabloMoney.buyin = parseFloat(document.getElementById('diabloBuyinAmount')?.value) || 5; diabloMoney.currentHole = 1; diabloMoney.frontierHole = 1; diabloMoney.scores = []; if (diabloMoney.format === 'money-doubles' && diabloMoney.teamAssignments && diabloMoney.teamAssignments.length) { diabloMoney.teamAssignments.forEach(team => { diabloMoney.scores.push({ teamKey: team.key, teamName: team.name, players: team.players, isCali: team.isCali || false, buyinMultiplier: team.buyinMultiplier || (team.isCali ? (diabloMoney.players.find(p=>p.cali)?.buyinMultiplier||1) : 2), holes: [], total: 0 }); }); } else { diabloMoney.scores = diabloMoney.players.map(p => ({ ...p, holes: [], total: 0 })); } try { const { data } = await db.from('diablo_money_matches').insert({ format: diabloMoney.format, status: 'active', players: JSON.stringify(diabloMoney.players), buyin: diabloMoney.buyin, total_holes: diabloMoney.totalHoles, current_hole: 1 }).select().single(); if (data) diabloMoney.matchId = data.id; } catch(e) { console.warn('startDiabloRound save:', e); } { const now = new Date().toISOString(); diabloMoney.players.forEach(pl => { if (pl && pl.name) diabloLastPlayed[pl.name] = now; }); } document.getElementById('diabloSetupScreen').style.display = 'none'; showDiabloScorecard(); }
function showDiabloScorecard() { let overlay = document.getElementById('diabloScorecardOverlay'); if (!overlay) { overlay = document.createElement('div'); overlay.id = 'diabloScorecardOverlay'; overlay.className = 'diablo-scorecard-overlay'; document.body.appendChild(overlay); } overlay.style.display = 'flex'; renderDiabloScorecardOverlay(); }
function hideDiabloScorecard() { const overlay = document.getElementById('diabloScorecardOverlay'); if (overlay) overlay.style.display = 'none'; }
function renderDiabloScorecardOverlay() { const overlay = document.getElementById('diabloScorecardOverlay'); if (!overlay) return; const h = diabloMoney.currentHole; const frontier = diabloMoney.frontierHole || 1; const viewingPast = h < frontier; const scores = diabloMoney.scores; const holesPlayed = Math.max(0, frontier - 1); const minTotal = scores.length ? Math.min(...scores.map(s => s.total || 0)) : 0; const isDoubles = diabloMoney.format === 'money-doubles'; const totalsHtml = scores.map(s => { const relPar = fmtRelPar(s.total || 0, holesPlayed); const sign = relPar === 'E' ? ' even' : (relPar.charAt(0) === '+' ? ' over' : ' under'); const isLead = (s.total || 0) === minTotal && holesPlayed > 0; return '<div class="dsc-total-chip' + (isLead ? ' leading' : '') + '"><div class="dsc-total-name">' + (s.teamName || s.name) + '</div><div class="dsc-total-score' + sign + '">' + relPar + '</div></div>'; }).join(''); const teamsHtml = scores.map((s, i) => { const existingScore = s.holes && s.holes[h-1] !== undefined ? s.holes[h-1] : null; const isActive = existingScore !== null && existingScore !== 2; const displayVal = existingScore !== null ? existingScore : 2; const isLeading = (s.total || 0) === minTotal && frontier > 1; const playerLine = isDoubles ? (s.players ? s.players.join(' \xb7 ') : (s.name || '')) : (s.name || ''); const caliLabel = s.isCali ? ' <span style="font-size:10px;color:#666;font-family:DM Mono,monospace;letter-spacing:1px;">CALI</span>' : ''; return '<div class="dsc-team-row" style="' + (isLeading ? 'border-color:#ffd700;' : '') + '"><div class="dsc-team-info"><div class="dsc-team-name">' + (s.teamName || s.name) + caliLabel + '</div><div class="dsc-team-players">' + playerLine + '</div></div><div class="dsc-score-control"><button class="dsc-score-btn" onclick="dscAdjust(' + i + ',-1)">−</button><div class="dsc-score-val ' + (isActive ? 'active' : 'default') + '" id="dsc_' + i + '" data-score="' + displayVal + '" onclick="dscActivate(' + i + ')">' + displayVal + '</div><button class="dsc-score-btn" onclick="dscAdjust(' + i + ',1)">+</button></div><div class="dsc-team-total' + (isLeading ? ' leading' : '') + (function(){ const r = fmtRelPar(s.total||0,holesPlayed); return r === 'E' ? ' even' : (r.charAt(0) === '+' ? ' over' : ' under'); })() + '" style="font-size:' + (fmtRelPar(s.total||0,holesPlayed).length > 3 ? '28px' : '38px') + ';">' + fmtRelPar(s.total||0,holesPlayed) + '</div></div>'; }).join(''); const dotsHtml = Array.from({length: diabloMoney.totalHoles}, (_, j) => { const hn = j + 1; const cls = hn === h ? 'current' : (hn < frontier ? 'done' : ''); const clickable = hn <= frontier; return '<div class="dsc-hole-dot ' + cls + '"' + (clickable ? ' onclick="dscGoToHole(' + hn + ')"' : ' style="opacity:0.35;cursor:default"') + '>' + hn + '</div>'; }).join(''); overlay.innerHTML = '<div class="dsc-header"><div><div class="dsc-hole-num">' + h + '</div><div class="dsc-hole-info">HOLE ' + h + ' OF ' + diabloMoney.totalHoles + ' \xb7 PAR 2</div></div><div class="dsc-totals-bar">' + totalsHtml + '</div></div><div class="dsc-teams" id="dscTeams">' + teamsHtml + '</div><div class="dsc-footer"><div class="dsc-hole-dots">' + dotsHtml + '</div><button class="diablo-btn diablo-btn-primary" onclick="dscNextHole()" style="width:100%;justify-content:center;font-size:20px;padding:16px;">' + (viewingPast ? 'Save &amp; Return to Hole ' + frontier : (h === diabloMoney.totalHoles ? 'FINISH ROUND \uD83D\uDD25' : 'Next Hole →')) + '</button>' + (viewingPast ? '<button class="diablo-btn diablo-btn-secondary" onclick="dscReturnToCurrent()" style="width:100%;justify-content:center;margin-top:8px;">↩ Return to Current (Hole ' + frontier + ')</button>' : '') + '<button class="diablo-btn diablo-btn-secondary" onclick="if(confirm(\'Abandon this round?\')){ hideDiabloScorecard(); closeDiabloPlay(); }" style="width:100%;justify-content:center;margin-top:8px;">✕ Abandon Round</button></div>'; }
function dscActivate(idx) { const el = document.getElementById('dsc_' + idx); if (!el) return; el.className = 'dsc-score-val active'; const score = parseInt(el.dataset.score) || 2; if (!diabloMoney.scores[idx].holes) diabloMoney.scores[idx].holes = []; diabloMoney.scores[idx].holes[diabloMoney.currentHole - 1] = score; }
function dscAdjust(idx, delta) { const el = document.getElementById('dsc_' + idx); if (!el) return; const current = parseInt(el.dataset.score) || 2; const newScore = Math.max(1, current + delta); el.dataset.score = newScore; el.textContent = newScore; el.className = 'dsc-score-val active'; if (!diabloMoney.scores[idx].holes) diabloMoney.scores[idx].holes = []; diabloMoney.scores[idx].holes[diabloMoney.currentHole - 1] = newScore; }
function dscGoToHole(holeNum) { const frontier = diabloMoney.frontierHole || 1; if (holeNum < 1 || holeNum > frontier) return; diabloMoney.currentHole = holeNum; renderDiabloScorecardOverlay(); }
function dscReturnToCurrent() { diabloMoney.currentHole = diabloMoney.frontierHole || 1; renderDiabloScorecardOverlay(); }
async function dscNextHole() { const h = diabloMoney.currentHole; const frontier = diabloMoney.frontierHole || 1; const holeScores = []; diabloMoney.scores.forEach((s, i) => { const el = document.getElementById('dsc_' + i); const score = el ? (parseInt(el.dataset.score) || 2) : 2; if (!s.holes) s.holes = []; s.holes[h-1] = score; s.total = s.holes.reduce((sum, v) => sum + (v || 2), 0); if (s.players) { s.players.forEach(name => holeScores.push({ match_id: diabloMoney.matchId, hole: h, player_name: name, score })); } else { holeScores.push({ match_id: diabloMoney.matchId, hole: h, player_name: s.name, score }); } }); try { if (diabloMoney.matchId) { await db.from('diablo_money_scores').delete().eq('match_id', diabloMoney.matchId).eq('hole', h); await db.from('diablo_money_scores').insert(holeScores); if (h >= frontier) { await db.from('diablo_money_matches').update({ current_hole: h + 1 }).eq('id', diabloMoney.matchId); } } } catch(e) { console.warn('save hole:', e); } if (h < frontier) { diabloMoney.currentHole = frontier; renderDiabloScorecardOverlay(); return; } if (h === diabloMoney.totalHoles) { hideDiabloScorecard(); showDiabloPayout(); return; } diabloMoney.frontierHole = h + 1; diabloMoney.currentHole = h + 1; renderDiabloScorecardOverlay(); }
function fmtRelPar(strokes, holesPlayed) { if (!holesPlayed) return 'E'; const par = holesPlayed * 2; const diff = strokes - par; if (diff === 0) return 'E'; if (diff > 0) return '+' + diff; return String(diff); }
function scoreLabel(strokes) { const diff = strokes - 2; if (diff <= -3) return 'Albatross'; if (diff === -2) return 'Eagle'; if (diff === -1) return 'Birdie'; if (diff === 0) return 'Par'; if (diff === 1) return 'Bogey'; if (diff === 2) return 'Double Bogey'; if (diff === 3) return 'Triple Bogey'; return '+' + diff; }
function renderDiabloHole() { showDiabloScorecard(); } function renderDiabloRunningTotals() {}
function activateDiabloScore(idx) { const display = document.getElementById('dhole_' + idx + '_display'); if (!display) return; display.style.color = '#ff6600'; display.style.borderColor = '#8b0000'; display.dataset.active = 'true'; const score = parseInt(display.dataset.score) || 2; if (!diabloMoney.scores[idx].holes) diabloMoney.scores[idx].holes = []; diabloMoney.scores[idx].holes[diabloMoney.currentHole - 1] = score; }
function adjustDiabloScore(idx, delta) { const display = document.getElementById('dhole_' + idx + '_display'); if (!display) return; const current = parseInt(display.dataset.score) || 2; const newScore = Math.max(1, current + delta); display.dataset.score = newScore; display.dataset.active = 'true'; display.textContent = newScore; display.style.color = '#ff6600'; display.style.borderColor = '#8b0000'; if (!diabloMoney.scores[idx].holes) diabloMoney.scores[idx].holes = []; diabloMoney.scores[idx].holes[diabloMoney.currentHole - 1] = newScore; }
async function diabloNextHole() { const h = diabloMoney.currentHole; const holeScores = []; diabloMoney.scores.forEach((p, i) => { const display = document.getElementById('dhole_' + i + '_display'); const score = display ? (parseInt(display.dataset.score) || 2) : 2; if (!p.holes) p.holes = []; p.holes[h-1] = score; holeScores.push({ match_id: diabloMoney.matchId, hole: h, player_name: p.name, score }); }); diabloMoney.scores.forEach(p => { p.total = p.holes.reduce((sum, s) => sum + (s || 2), 0); }); try { if (diabloMoney.matchId) { await db.from('diablo_money_scores').insert(holeScores); await db.from('diablo_money_matches').update({ current_hole: h + 1 }).eq('id', diabloMoney.matchId); } } catch(e) { console.warn('save hole:', e); } if (h === diabloMoney.totalHoles) { showDiabloPayout(); return; } diabloMoney.currentHole++; renderDiabloHole(); renderDiabloRunningTotals(); }
async function showDiabloPayout() { document.getElementById('diabloScorecardScreen').style.display = 'none'; document.getElementById('diabloPayoutScreen').style.display = 'block'; const buyin = diabloMoney.buyin; const isDoubles = diabloMoney.format === 'money-doubles'; let winnerLabel = '', winnerPlayers = [], loserPlayers = [], payoutPerWinner = 0, payoutSub = '', finalScoresHtml = '', teamArr = null; if (isDoubles) { teamArr = diabloMoney.scores.map(s => ({ label: (s.teamName || s.name || '?') + (s.isCali ? ' (Cali)' : ''), total: s.total || 0, players: s.players && s.players.length ? s.players : (s.name ? [s.name] : []), holes: s.holes, isCali: !!s.isCali, pot: buyin * (s.isCali ? (s.buyinMultiplier || 1) : 2) })); const winner = teamArr.reduce((a,b) => a.total < b.total ? a : b); const totalPotAll = teamArr.reduce((s,t) => s + t.pot, 0); const winnerContrib = winner.pot; const loserPot = totalPotAll - winnerContrib; payoutPerWinner = winner.players.length ? loserPot / winner.players.length : loserPot; winnerLabel = (winner.isCali && winner.players.length === 1) ? winner.label : winner.label + ' (' + winner.players.join(' + ') + ')'; winnerPlayers = winner.players; loserPlayers = teamArr.filter(t => t !== winner).flatMap(t => t.players); const winnerHoles = winner.holes ? winner.holes.filter(h => h !== undefined).length : diabloMoney.totalHoles; payoutSub = fmtRelPar(winner.total, winnerHoles) + ' \xb7 Each winner collects $' + payoutPerWinner.toFixed(0); finalScoresHtml = teamArr.sort((a,b) => a.total - b.total).map((t,i) => '<div style="display:flex;justify-content:space-between;padding:10px 14px;background:#1a0000;border:1px solid #8b0000;border-radius:8px;margin-bottom:8px;">' + '<span style="color:#ffcccc;font-weight:500;">' + t.label + ' — ' + t.players.join(' + ') + '</span>' + '<span style="font-family:Bebas Neue,sans-serif;font-size:22px;color:' + (i===0?'#ffd700':'#8b0000') + '">' + t.total + '</span>' + '</div>' ).join(''); } else { const sorted = [...diabloMoney.scores].sort((a,b) => a.total - b.total); const winner = sorted[0]; const loserPot = sorted.slice(1).reduce((s,p) => s + buyin * (p.buyinMultiplier || 1), 0); payoutPerWinner = loserPot; winnerLabel = winner.name; winnerPlayers = [winner.name]; loserPlayers = sorted.slice(1).map(p => p.name); payoutSub = fmtRelPar(winner.total, diabloMoney.totalHoles) + ' \xb7 Winner collects $' + payoutPerWinner.toFixed(0); finalScoresHtml = sorted.map((p,i) => '<div style="display:flex;justify-content:space-between;padding:10px 14px;background:#1a0000;border:1px solid #8b0000;border-radius:8px;margin-bottom:8px;"><span style="color:#ffcccc;font-weight:500;">' + p.name + '</span><span style="font-family:Bebas Neue,sans-serif;font-size:22px;color:' + (i===0?'#ffd700':'#8b0000') + '">' + p.total + '</span></div>').join(''); } document.getElementById('diabloWinnerName').textContent = winnerLabel; document.getElementById('diabloPayoutAmount').textContent = '$' + payoutPerWinner.toFixed(0); document.getElementById('diabloPayoutSub').textContent = payoutSub; document.getElementById('diabloFinalScores').innerHTML = finalScoresHtml; try { if (diabloMoney.matchId) { await db.from('diablo_money_matches').update({ status: 'complete', completed_at: new Date().toISOString() }).eq('id', diabloMoney.matchId); const totalPot = isDoubles ? teamArr.reduce((s,t) => s + t.pot, 0) : diabloMoney.players.reduce((s,p) => s + buyin * (p.buyinMultiplier||1), 0); await db.from('diablo_money_history').insert({ match_id: diabloMoney.matchId, format: diabloMoney.format, winner_label: winnerLabel, winner_players: JSON.stringify(winnerPlayers), loser_players: JSON.stringify(loserPlayers), payout_per_winner: payoutPerWinner, total_pot: totalPot, date: localDateStr() }); for (const name of winnerPlayers) { await db.from('diablo_player_stats').upsert({ player_name: name }, { onConflict: 'player_name' }); const { data: ps } = await db.from('diablo_player_stats').select('*').eq('player_name', name).single(); if (ps) { await db.from('diablo_player_stats').update({ matches_played: (ps.matches_played||0)+1, matches_won: (ps.matches_won||0)+1, total_winnings: (ps.total_winnings||0)+payoutPerWinner, biggest_payout: Math.max(ps.biggest_payout||0, payoutPerWinner) }).eq('player_name', name); } } for (const name of loserPlayers) { await db.from('diablo_player_stats').upsert({ player_name: name }, { onConflict: 'player_name' }); const { data: ps } = await db.from('diablo_player_stats').select('*').eq('player_name', name).single(); if (ps) { await db.from('diablo_player_stats').update({ matches_played: (ps.matches_played||0)+1, total_losses: (ps.total_losses||0)+buyin }).eq('player_name', name); } } } } catch(e) { console.warn('payout save:', e); } loadDiabloLastWin(); loadDiabloStats(); }
async function loadDiabloLastWin() { try { const { data } = await db.from('diablo_money_history').select('*').order('created_at',{ascending:false}).limit(1); if (data && data.length) { const h = data[0]; document.getElementById('diabloLastWin').style.display = 'block'; document.getElementById('diabloLastWinName').textContent = h.winner_label + ' 💰 $' + parseFloat(h.payout_per_winner).toFixed(0) + ' each'; document.getElementById('diabloLastWinDetail').textContent = h.date + ' · ' + (h.format === 'tags' ? 'Tag Match' : h.format.includes('doubles') ? 'Doubles' : 'Singles') + ' · Pot: $' + parseFloat(h.total_pot).toFixed(0); } } catch(e) { console.warn('loadDiabloLastWin:', e); } }
async function loadDiabloStats() { try { const { data } = await db.from('diablo_player_stats').select('*').order('total_winnings',{ascending:false}).limit(10); if (data && data.length) { document.getElementById('diabloStatsCard').style.display = 'block'; document.getElementById('diabloStatsList').innerHTML = data.map(p => '<div class="diablo-stats-row"><span class="diablo-stats-name">' + p.player_name + '</span><span style="font-size:11px;color:#8b0000;font-family:DM Mono,monospace;margin-right:8px;">' + (p.matches_won||0) + 'W/' + ((p.matches_played||0)-(p.matches_won||0)) + 'L</span><span class="diablo-stats-val positive">$' + parseFloat(p.total_winnings||0).toFixed(0) + '</span></div>').join(''); } } catch(e) { console.warn('loadDiabloStats:', e); } }
